// Decides "create" or "update" and builds the HubSpot properties to send.
// Data rules (agreed with sales, written down in the README):
//   1. Never overwrite CRM data with a blank value.
//   2. Name and company are only filled when empty in the CRM (sales may have corrected them).
//   3. Phone, job title and message come from the latest submission, so the form wins.
//   4. Lifecycle stage only moves forward: a "customer" is never pushed back to "lead".
const { lead } = $('Normalize & Validate').first().json;
const search = $input.first().json;
const existing = (search.results || [])[0];
const current = existing ? existing.properties || {} : {};

const fromForm = {
  email: lead.email,
  firstname: lead.first_name,
  lastname: lead.last_name,
  company: lead.company,
  website: lead.website,
  phone: lead.phone,
  jobtitle: lead.job_title,
  message: lead.message,
};
const FILL_IF_EMPTY = ['firstname', 'lastname', 'company', 'website'];
const FORM_WINS = ['phone', 'jobtitle', 'message'];

const properties = {};
const changed = [];
for (const [key, value] of Object.entries(fromForm)) {
  if (!value) continue; // rule 1
  if (!existing) { properties[key] = value; continue; }
  const old = current[key] || '';
  if (old === value) continue;
  if (FILL_IF_EMPTY.includes(key) && old) continue; // rule 2
  if (FILL_IF_EMPTY.includes(key) || FORM_WINS.includes(key)) {
    properties[key] = value;
    changed.push(old ? `${key}: "${old}" → "${value}"` : `${key}: set to "${value}"`);
  }
}

// Rule 4. HubSpot's default stages, in order.
const STAGES = ['subscriber', 'lead', 'marketingqualifiedlead', 'salesqualifiedlead', 'opportunity', 'customer', 'evangelist'];
const currentStage = STAGES.indexOf(current.lifecyclestage || '');
if (!existing) {
  properties.lifecyclestage = 'lead';
  properties.hs_lead_status = 'NEW';
} else if (currentStage < STAGES.indexOf('lead')) {
  properties.lifecyclestage = 'lead';
  changed.push(`lifecyclestage: "${current.lifecyclestage || '(empty)'}" → "lead"`);
}

return [{
  json: {
    action: existing ? 'update' : 'create',
    contact_id: existing ? existing.id : '',
    current_lifecycle: current.lifecyclestage || '',
    current_owner_id: current.hubspot_owner_id || '',
    properties,
    changed_fields: changed,
  },
}];

// Merges the form data and the HubSpot response into one row for the "Leads" sheet.
// Runs after either "HubSpot · Update Contact" (returns {id}) or "HubSpot · Create Contact" (batch upsert, returns {results:[{id, new}]}).
const response = $input.first().json;
const payload = $('Build CRM Payload').first().json;
const { lead, warnings, received_at } = $('Normalize & Validate').first().json;

const upserted = (response.results || [])[0];
const contactId = response.id || (upserted && upserted.id) || payload.contact_id;
// The upsert endpoint is race-safe: if the same person submitted twice within seconds,
// the second call updates the contact created by the first one instead of duplicating it.
const action = payload.action === 'create' && upserted && upserted.new === false ? 'update' : payload.action;

return [{
  json: {
    email: lead.email,
    first_name: lead.first_name,
    last_name: lead.last_name,
    phone: lead.phone,
    company: lead.company,
    job_title: lead.job_title,
    website: lead.website,
    message: lead.message,
    consent: lead.consent ? 'yes' : 'no',
    form_name: lead.form_name,
    page_url: lead.page_url,
    utm_source: lead.utm_source,
    utm_medium: lead.utm_medium,
    utm_campaign: lead.utm_campaign,
    hubspot_contact_id: contactId,
    crm_action: action,
    changed_fields: payload.changed_fields.join('; '),
    warnings: warnings.join('; '),
    last_submitted_at: received_at,
    submission_id: lead.submission_id,
    // Reset on every submission so the SLA monitor (project 05) starts a new clock.
    sla_level: '',
    sla_alerted_at: '',
  },
}];

// Builds the internal notification email. Every value typed by the visitor is HTML-escaped,
// so a message containing <script> or a fake link cannot inject markup into the sales inbox.
const row = $input.first().json;
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const name = [row.first_name, row.last_name].filter(Boolean).join(' ') || row.email;
const isNew = row.crm_action === 'create';
const badge = isNew ? '🆕 New contact' : '🔁 Returning contact';

const line = (label, value) => (value ? `<tr><td style="padding:4px 12px 4px 0;color:#666">${esc(label)}</td><td style="padding:4px 0">${esc(value)}</td></tr>` : '');
const campaign = [row.utm_source, row.utm_medium, row.utm_campaign].filter(Boolean).join(' / ');

const html = `
<div style="font-family:Arial,sans-serif;font-size:14px;color:#222;max-width:600px">
  <h2 style="margin:0 0 4px">${esc(name)}${row.company ? ` · ${esc(row.company)}` : ''}</h2>
  <p style="margin:0 0 16px;color:#555">${badge} · form: ${esc(row.form_name)}</p>
  <table style="border-collapse:collapse">
    ${line('Email', row.email)}
    ${line('Phone', row.phone)}
    ${line('Job title', row.job_title)}
    ${line('Website', row.website)}
    ${line('Campaign', campaign)}
    ${line('Page', row.page_url)}
    ${line('HubSpot ID', row.hubspot_contact_id)}
  </table>
  <h3 style="margin:16px 0 4px">Message</h3>
  <p style="white-space:pre-wrap;background:#f6f6f6;padding:12px;border-radius:6px;margin:0">${esc(row.message) || '<i>(no message)</i>'}</p>
  ${row.changed_fields ? `<p style="color:#555"><b>CRM fields updated:</b> ${esc(row.changed_fields)}</p>` : ''}
  ${row.warnings ? `<p style="color:#b45309"><b>⚠️ Check:</b> ${esc(row.warnings)}</p>` : ''}
</div>`;

return [{
  json: {
    email_subject: `${isNew ? 'New lead' : 'Returning lead'}: ${name}${row.company ? ` (${row.company})` : ''}`,
    email_html: html,
  },
}];

// Runs when a HubSpot call still fails after 3 retries (token expired, HubSpot outage, rate limit).
// The visitor already got "202 Accepted", so the lead must not be lost: it goes into the
// "Failed Syncs" sheet, and the retry worker (project 03) pushes it to HubSpot later.
const { lead } = $('Normalize & Validate').first().json;
const failure = $input.first().json;
const err = typeof failure.error === 'object' && failure.error ? failure.error : { message: failure.error || failure.message };

// Properties may not exist yet if the first HubSpot call (search) failed. Fall back to a plain mapping.
let properties;
try {
  properties = $('Build CRM Payload').first().json.properties;
} catch (e) {
  properties = Object.fromEntries(Object.entries({
    email: lead.email, firstname: lead.first_name, lastname: lead.last_name, company: lead.company,
    website: lead.website, phone: lead.phone, jobtitle: lead.job_title, message: lead.message,
  }).filter(([, v]) => v));
}

const now = new Date();
const code = String(err.httpCode || err.status || (String(err.message || '').match(/\b([45]\d\d)\b/) || [])[1] || '');

return [{
  json: {
    queue_id: `Q-${now.getTime().toString(36).toUpperCase()}-${Math.random().toString(36).slice(2, 6).toUpperCase()}`,
    created_at: now.toISOString(),
    source_workflow: '01 · Form → CRM',
    stage: $prevNode.name,
    email: lead.email,
    payload: JSON.stringify(properties),
    attempts: 0,
    status: 'pending',
    next_retry_at: new Date(now.getTime() + 15 * 60 * 1000).toISOString(),
    last_error_code: code,
    last_error: String(err.message || 'unknown error').slice(0, 500),
    resolved_at: '',
    hubspot_contact_id: '',
  },
}];
